	'i_mod_m3b1' => 'Métaux aéronautiques, composites, corrosion et méthodes de traitement',
	'i_mod_m3b2' => 'Fixations, freinage au fil de fer, goupilles fendues et pratique du serrage au couple',
	'i_mod_m3b3' => 'Outillage à main, métrologie et rigueur d\'étalonnage',
